<script setup>import{Head,useForm}from'@inertiajs/vue3';import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';const p=defineProps({settings:Object,telegram:Object});const f=useForm({...p.settings,telegram_enabled:p.telegram?.enabled||false,telegram_bot_token:'',telegram_chat_id:''});</script><template><Head title="Settings"/><AuthenticatedLayout><template #header><div><h1 class="text-lg font-semibold text-white">Monitoring settings</h1><p class="text-xs text-slate-500">System defaults, retention, and notifications</p></div></template><form @submit.prevent="f.put(route('settings.update'))" class="mx-auto max-w-3xl space-y-5"><section class="rounded-xl border border-slate-800 bg-slate-900 p-6"><h2 class="mb-5 font-semibold text-white">Default checks</h2><div class="grid gap-5 sm:grid-cols-2"><label>Interval (seconds)<input v-model="f.default_interval_seconds" type="number" class="field"></label><label>Timeout (ms)<input v-model="f.default_timeout_ms" type="number" class="field"></label><label>Retry count<input v-model="f.default_retry_count" type="number" class="field"></label><label>Latency threshold (ms)<input v-model="f.default_latency_threshold_ms" type="number" class="field"></label><label>History retention (days)<input v-model="f.history_retention_days" type="number" class="field"></label></div></section><section class="rounded-xl border border-slate-800 bg-slate-900 p-6"><h2 class="font-semibold text-white">Telegram alerts</h2><p class="mb-5 text-xs text-slate-500">Credentials are encrypted at rest. Leave blank to retain existing values.</p><div class="grid gap-5 sm:grid-cols-2"><label>Bot token<input v-model="f.telegram_bot_token" type="password" class="field"></label><label>Chat ID<input v-model="f.telegram_chat_id" class="field"></label><label class="flex gap-3"><input v-model="f.telegram_enabled" type="checkbox"> Enable Telegram</label></div></section><button class="rounded-lg bg-emerald-500 px-5 py-2 font-bold text-slate-950">Save settings</button></form></AuthenticatedLayout></template>
